function waveAct(k,p){
 switch(k){
 case 'noop':return true;
 case 'lit':{S.lit=!(S.lit===undefined?true:S.lit);return true}
 case 'rxs':{S.rxMine=(rxMine()===p[0]?null:p[0]);S.rxSticker=undefined;return true}
 case 'rxp':{S.rxMine=(rxMine()===p[0]?null:p[0]);S.rxSticker=undefined;S.wst='chat';return true}
 case 'rxst':{S.rxSticker=(S.rxSticker===p[0]?undefined:p[0]);S.rxMine=null;S.wst='chat';return true}
 case 'wst':S.wst=p[0];return true;
 case 'wstp':push();S.wst=p[0];return true;
 case 'go':{push();S.screen=p[0];if(p[0]==='3')setS3(p[1]);else if(WST[p[0]])S.wst=p[1];return true}
 }
 return false}
